  api("GET", `/incidents`, undefined);   // api(): see get_guide('envelope-and-errors')

// One incident  (permissions: any logged-in user)
export const getIncident = (incident_id) =>
  api("GET", `/incidents/${incident_id}`, undefined);   // api(): see get_guide('envelope-and-errors')

// The list of sentinel events and how to report (PDF)  (permissions: any logged-in user)
export const sentinelListPdf = () =>
  api("GET", `/incidents/sentinel-list/pdf`, undefined);   // api(): see get_guide('envelope-and-errors')

// One approval request  (permissions: any logged-in user)
export const getApproval = (request_id) =>
  api("GET", `/approvals/${request_id}`, undefined);   // api(): see get_guide('envelope-and-errors')

// Approve (applies the effect atomically)  (permissions: any logged-in user)
export const approve = (request_id, body) =>
  api("POST", `/approvals/${request_id}/approve`, body);   // api(): see get_guide('envelope-and-errors')

// Reject (unfreezes the subject)  (permissions: any logged-in user)
export const reject = (request_id, body) =>
  api("POST", `/approvals/${request_id}/reject`, body);   // api(): see get_guide('envelope-and-errors')

// Requester withdraws a pending request  (permissions: any logged-in user)
export const cancelApprovals = (request_id, body) =>
  api("POST", `/approvals/${request_id}/cancel`, body);   // api(): see get_guide('envelope-and-errors')

// The end-user handbook's outline for the logged-in employee (only what they may use)  (permissions: any logged-in user)
export const endUserHandbook = () =>
  api("GET", `/meta/handbook`, undefined);   // api(): see get_guide('envelope-and-errors')

// How terminals reach and trust this server — works before login  (permissions: any logged-in user)
export const serverInfo = () =>
  api("GET", `/meta/server-info`, undefined);   // api(): see get_guide('envelope-and-errors')
